import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.Id;
import jakarta.persistence.Table;

import java.util.UUID;

@Entity
@Table(name = "book")
public class BookJpaEntity {

    @Id
    private UUID id;

    @Column(nullable = false)
    private String title;

    @Column(nullable = false)
    private String status;

    protected BookJpaEntity() {
    }

    public BookJpaEntity(UUID id, String title, String status) {
        this.id = id;
        this.title = title;
        this.status = status;
    }

    public UUID getId() {
        return id;
    }

    public String getTitle() {
        return title;
    }

    public String getStatus() {
        return status;
    }
}
package com.example.lending.adapter.out.persistence;

import com.example.lending.domain.Book;
import com.example.lending.domain.BookStatus;

class BookMapper {

    Book toDomain(BookJpaEntity entity) {
        return Book.reconstitute(entity.getId(), entity.getTitle(), BookStatus.valueOf(entity.getStatus()));
    }

    BookJpaEntity toEntity(Book book) {
        return new BookJpaEntity(book.getId(), book.getTitle(), book.getStatus().name());
    }
}
package com.example.lending.domain;

import java.util.Objects;
import java.util.UUID;

public class Book {

    private final UUID id;
    private final String title;
    private BookStatus status;

    private Book(UUID id, String title, BookStatus status) {
        this.id = Objects.requireNonNull(id, "id");
        if (title == null || title.isBlank()) {
            throw new IllegalArgumentException("title must not be blank");
        }
        this.title = title;
        this.status = Objects.requireNonNull(status, "status");
    }

    public static Book register(String title) {
        return new Book(UUID.randomUUID(), title, BookStatus.AVAILABLE);
    }

    public static Book reconstitute(UUID id, String title, BookStatus status) {
        return new Book(id, title, status);
    }

    public UUID getId() {
        return id;
    }

    public String getTitle() {
        return title;
    }

    public BookStatus getStatus() {
        return status;
    }

    public void setStatus(BookStatus status) {
        this.status = status;
    }
}
package com.example.lending.domain;

public enum BookStatus {
    AVAILABLE,
    ON_LOAN
}

