    public void saveLoan(Loan loan) {
        loanJpaRepository.save(loanMapper.toEntity(loan));
    }

    @Override
    public long countActiveLoansByMemberId(UUID memberId) {
        return loanJpaRepository.countByMemberIdAndReturnedAtIsNull(memberId);
    }

    @Override
    public Optional<Loan> loadLoanForUpdate(UUID loanId) {
        return loanJpaRepository.findForUpdateById(loanId).map(loanMapper::toDomain);
    }

    @Override
    public ActiveLoanPage loadActiveLoans(UUID memberId, int page, int size) {
        List<ActiveLoan> items = loanJpaRepository.findActiveLoanRows(memberId, PageRequest.of(page, size))
                .stream()
                .map(row -> new ActiveLoan(row.getLoanId(), row.getBookId(), row.getTitle(),
                        row.getLoanedAt(), row.getDueAt()))
                .toList();
        return new ActiveLoanPage(items, countActiveLoansByMemberId(memberId));
    }
}

