package com.example.lending;

import com.fasterxml.jackson.databind.ObjectMapper;
import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.http.MediaType;
import org.springframework.test.web.servlet.MockMvc;

import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.get;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.post;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.jsonPath;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.status;

@SpringBootTest
@AutoConfigureMockMvc
class BookSearchIntegrationTest {

    @Autowired
    MockMvc mockMvc;

    @Autowired
    ObjectMapper objectMapper;

    @Test
    void title_part_matches_ignoring_case() throws Exception {
        registerBook("Spring in Action");

        mockMvc.perform(get("/books").param("title", "spring"))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.length()").value(1))
                .andExpect(jsonPath("$[0].title").value("Spring in Action"))
                .andExpect(jsonPath("$[0].status").value("AVAILABLE"));
    }

    @Test
    void every_book_whose_title_contains_the_keyword_is_returned() throws Exception {
        registerBook("Spring in Action");
        registerBook("Spring Boot Guide");
        registerBook("Clean Code");

        mockMvc.perform(get("/books").param("title", "SPRING"))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.length()").value(2))
                .andExpect(jsonPath("$[*].title").value(org.hamcrest.Matchers.containsInAnyOrder(
                        "Spring in Action", "Spring Boot Guide")));
    }

    @Test
    void no_matching_book_returns_empty_list() throws Exception {
        registerBook("Clean Code");

        mockMvc.perform(get("/books").param("title", "kotlin"))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$").isEmpty());
    }

    @Test
    void wildcard_characters_in_keyword_are_matched_literally() throws Exception {
        registerBook("Clean Code");

        mockMvc.perform(get("/books").param("title", "%"))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$").isEmpty());
        mockMvc.perform(get("/books").param("title", "_"))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$").isEmpty());
